    .watermark {
          position: absolute;
          left: 0;
          top: 0;
          animation-name: animation2, blinker;
          animation-duration: 40s;
          animation-iteration-count: infinite;
          color: red;
          z-index: 999;
          font-size: 15px;
          font-weight: 600;
    }

   @keyframes animation2 {
      0% {left: 0;top:0;}
      10% {left: 20%;top:20%;}
      20% {left: 30%;top:80%;}
      30% {left: 10%;top:90%;}
      40% {left: 80%;top:80%;}
      50% {left: 90%;top:10%;}
      60% {left: 70%;top:50%;}
      70% {left: 45%;top:30%;}
      80% {left: 50%;top:50%;}
      90% {left: 90%;top:25%;}
      100% {left: 0;top:0;}
    } 


@keyframes blinker {
  0% {opacity: 1.0;}
  10% {opacity: 0.0;}
  20% {opacity: 1.0;}
  30% {opacity: 0.0;}
  40% {opacity: 1.0;}
  50% {opacity: 0.0;}
  60% {opacity: 1.0;}
  70% {opacity: 0.0;}
  80% {opacity: 1.0;}
  90% {opacity: 0.0;}
  100% {opacity: 1.0;}
}



