     bottom: 20px;
     left: 50%;
     transition: all 200ms;
     display: flex;
     justify-content: center;
     flex-direction: column-reverse;
     width: 100px;
     transform: translate(-50%, -20px);
     visibility: hidden;
     opacity: 0;
 }
 .contentMenu .menu:hover {
